{"command": "python3 << 'EOF'
from PIL import Image, ImageDraw
img = Image.open('radiograph.jpg').convert('RGB')

def gridcrop(x1,y1,x2,y2,name,scale,step=25):
    c = img.crop((x1,y1,x2,y2))
    c = c.resize((c.width*scale, c.height*scale), Image.LANCZOS)
    d = ImageDraw.Draw(c)
    for x in range(x1, x2, step):
        px = (x-x1)*scale
        d.line([(px,0),(px,c.height)], fill=(255,0,0), width=1)
        if (x-x1)%(step*2)==0: d.text((px+2,2), str(x), fill=(255,0,0))
    for y in range(y1, y2, step):
        py = (y-y1)*scale
        d.line([(0,py),(c.width,py)], fill=(0,150,255), width=1)
        if (y-y1)%(step*2)==0: d.text((2,py+2), str(y), fill=(0,150,255))
    c.save(f'/tmp/{name}.png'); print(name, c.size)

gridcrop(700, 820, 1000, 1030, 'g_4647', 5, 25)
gridcrop(1600, 820, 1950, 1030, 'g_3637', 5, 25)
EOF", "description": "Gridded 5x crops of lower molar apex regions"}
